export function CardFooter({
  primaryLabel = "{{primaryLabel}}",
  secondaryLabel = "{{secondaryLabel}}",
  showSecondary = {{showSecondary}},
  color = "{{color}}",
}) {
  return (
    <footer style={{ display: "flex", justifyContent: "flex-end", gap: 8, font: "13px system-ui, sans-serif", borderTop: "1px solid #24143018", paddingTop: 12 }}>
      {showSecondary && (
        <button type="button" style={{ border: "1.5px solid #24143022", borderRadius: 8, padding: "8px 14px", fontWeight: 600, fontSize: 13, cursor: "pointer", background: "transparent", color: "#241430" }}>
          {secondaryLabel}
        </button>
      )}
      <button type="button" style={{ border: "none", borderRadius: 8, padding: "8px 14px", fontWeight: 600, fontSize: 13, cursor: "pointer", background: color, color: "#241430" }}>
        {primaryLabel}
      </button>
    </footer>
  );
}
